        private void xrTableCell7_SummaryGetResult(object sender, SummaryGetResultEventArgs e)
        {
	XRLabel p = (XRLabel) sender;
	XtraReport report = (XtraReport)p.Report;
	int shifraPasPresjes = (int)report.Parameters["parameterFormatNumri"].Value;
            //xrLabel17_SummaryGetResult Group header 3
            double shuma = 0;
