private void xrTableCell41_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
XRLabel p = (XRLabel) sender;
	XtraReport report = (XtraReport)p.Report;
	int shifraPasPresjes = (int)report.Parameters["parameterFormatNumri"].Value;
            //xrLabel16_SummaryGetResult
            double shuma = 0;
            for (int i = 0; i < e.CalculatedValues.Count; i++)
                if (e.CalculatedValues[i].ToString().Contains("("))
                    shuma -= double.Parse(e.CalculatedValues[i].ToString().Replace('(', ' ').Replace(')', ' '));
                else shuma += double.Parse(e.CalculatedValues[i].ToString());
            if (shuma >= 0)
                e.Result =  shuma.ToString("N" + shifraPasPresjes);
            else e.Result ="(" + (-shuma).ToString("N" + shifraPasPresjes) + ")";
            e.Handled = true;
        }

